// ─────────────────────────────────────────────────────────────
// EDIT THESE BEFORE ACTIVATING — same values in all three workflows
// ─────────────────────────────────────────────────────────────
const APP_URL        = 'https://YOUR-APP.vercel.app';
const WEBHOOK_SECRET = 'CHANGE_ME_same_as_N8N_WEBHOOK_SECRET';
const SUPABASE_URL   = 'https://YOUR-PROJECT.supabase.co';
const SUPABASE_KEY   = 'YOUR_SERVICE_ROLE_KEY';
const SCRAPER_URL    = 'https://YOUR-SCRAPER.vercel.app';
const SCRAPER_SECRET = 'CHANGE_ME_same_as_SCRAPER_SECRET';

// Listings pulled per search term, per source.
const LIMIT_PER_TERM = 40;

// Company slugs for the ATS sources — first-party listings, free, but you have
// to name the companies. Grow this list over time.
const ATS = { greenhouse: [], ashby: [], workable: [] };

// Jobs sent to the model in one request.
const SCORE_BATCH_SIZE = 15;

const MODELS = {
  anthropic: 'claude-opus-5',
  openai:    'gpt-4o-mini',
  gemini:    'gemini-2.0-flash',
  groq:      'llama-3.3-70b-versatile'
};

return { json: {
  appUrl: APP_URL, webhookSecret: WEBHOOK_SECRET,
  supabaseUrl: SUPABASE_URL, supabaseKey: SUPABASE_KEY,
  scraperUrl: SCRAPER_URL, scraperSecret: SCRAPER_SECRET,
  limitPerTerm: LIMIT_PER_TERM, ats: ATS,
  scoreBatchSize: SCORE_BATCH_SIZE, models: MODELS
} };

// One item per (user, term). A user's paid token only ever runs that user's own
// search — the results land in the shared pool and help everyone, but nobody's
// credits are spent on a search they did not ask for.
const payload = $input.first().json;
const body = Array.isArray(payload.apifyUsers) ? payload : payload.body;
const users = (body && body.apifyUsers) || [];

if (users.length === 0) {
  console.log('No users have connected an Apify token — nothing to do.');
  return [];
}

const out = [];
for (const u of users) {
  for (const term of u.terms) {
    const country = u.worldwide ? null : (u.countries[0] || null);
    out.push({ json: {
      _target: { term, countryCode: country, worldwide: !!u.worldwide },
      userId: u.userId, apifyKey: u.apifyKey, term,
      countryCode: country, worldwide: u.worldwide, workPreference: u.workPreference,
      // Empty means "the catalogue defaults" to the scraper service, not "none".
      apifyActors: u.apifyActors || []
    } });
  }
}
console.log('Apify: ' + out.length + ' run(s) across ' + users.length + ' user(s)');
return out;

// Builds one request to the scraper service's Apify endpoint.
//
// This node used to build the input for a single hardcoded actor
// (bebity~linkedin-jobs-scraper) and the next node ran it directly. Every actor
// has a different input schema, so adding a second one meant a second node, a
// second normaliser and a second set of enum mappings pasted in here.
//
// The catalogue now lives in services/scraper/src/apify/catalogue.ts, which
// knows each actor's input shape, output shape, coverage and price. n8n just
// says what the user wants and which actors they enabled.
const p = $input.item.json;

return { json: { ...p, apifyRequest: {
  apifyToken: p.apifyKey,
  query: p.term,
  countries: p.countryCode ? [p.countryCode] : [],
  worldwide: !!p.worldwide,
  workPreference: p.workPreference || [],
  // The user's marketplace selection. Omitted entirely when empty so the
  // service applies its own defaults rather than being told to run nothing.
  actors: (p.apifyActors && p.apifyActors.length) ? p.apifyActors : undefined,
  limit: 40,
  maxAgeDays: 7
} } };

// The scraper service already emits the unified schema — same as the free
// collector — so there is nothing to map, only to attach the target country and
// surface each actor's outcome.
//
// The hand-rolled normaliser this replaces read every field from a list of
// likely names because actor output is not a versioned contract. That problem
// did not go away; it moved to src/apify/catalogue.ts, where it is typed,
// probeable and shared with the free sources' filters and sanitiser.
const target = $('Apify Loop').first().json._target || {};
const payload = $input.first().json;
const body = payload && (Array.isArray(payload.jobs) ? payload : payload.body);

if (!body || !Array.isArray(body.jobs)) {
  console.log('Apify endpoint returned nothing usable: ' + JSON.stringify(payload).substring(0, 300));
  return [{ json: { _target: target } }];
}

// Per-actor, because the user paid for each one separately. `fetched` is what
// the actor returned and `count` is what survived filtering — an actor billing
// for rows that are all discarded is a setting worth turning off.
for (const r of (body.meta?.actors || [])) {
  console.log('  ' + String(r.source).padEnd(20) + (r.ok ? 'ok  ' : 'FAIL') +
    ' kept ' + r.count + ' of ' + (r.fetched == null ? '?' : r.fetched) +
    ' in ' + r.ms + 'ms' + (r.error ? ' - ' + r.error : ''));
}

if (body.jobs.length === 0) return [{ json: { _target: target } }];
return body.jobs.map(j => ({ json: { ...j, _countryCode: target.countryCode, _target: target } }));

// Shapes collected jobs into `jobs` rows.
//
// Everything that reaches a typed column is validated here: this is a bulk
// insert, so one unparseable timestamp or out-of-range enum fails every row in
// the batch rather than only its own.
/*
 * jobs.source_id is a FK, and a source missing from the table fails the whole
 * bulk insert with 23503 rather than just its own row. Hardcoded ids drifted
 * from the table once already, so resolve by name at run time instead: the
 * names come from the scraper source keys, and an unknown one degrades to a
 * null source_id — an unattributed job still belongs in the pool.
 *
 * Both LinkedIn paths (guest scrape and Apify actor) attribute to one row, as
 * do both Indeed paths.
 */
const SOURCE_ALIASES = { linkedin: 'apify_linkedin', indeed: 'apify_indeed' };
const sourceIdByName = new Map(
  $('Fetch Sources').all()
    .map(i => i.json)
    .filter(s => s && s.name)
    .map(s => [String(s.name), s.id])
);
if (sourceIdByName.size === 0) console.log('WARNING: no sources loaded — every source_id will be null');
function toSourceId(key) {
  if (!key) return null;
  return sourceIdByName.get(SOURCE_ALIASES[key] || String(key)) ?? null;
}
const JOB_TYPES = ['remote', 'onsite', 'hybrid'];

/*
 * Anything a source calls a date, turned into ISO or null.
 *
 * A plain `new Date(v)` is not enough: Indeed and Wuzzuf report "8 days ago"
 * and "Just posted", which parse as Invalid Date and would silently discard a
 * real posting date. The scraper service already normalises its own sources,
 * but Apify actor output arrives raw, so the parser has to live here too.
 * Null is still the fallback — `posted_at_source` is timestamptz and this
 * insert is bulk, so one bad value fails every row in the batch.
 */
function toTimestamp(value) {
  if (value === null || value === undefined) return null;

  if (typeof value === 'number' && isFinite(value)) {
    const d = new Date(value > 1e12 ? value : value * 1000);
    return isNaN(d.getTime()) ? null : d.toISOString();
  }

  const raw = String(value).trim();
  if (!raw) return null;
  const lower = raw.toLowerCase();

  if (/^(just posted|just now|today|active today|posted today|new)$/.test(lower)) return new Date().toISOString();
  if (/^(yesterday|posted yesterday)$/.test(lower)) return new Date(Date.now() - 864e5).toISOString();

  const rel = lower.match(/^(?:posted\s+|active\s+)?(\d+)\+?\s*(minute|hour|day|week|month|year)s?\s+ago$/);
  if (rel) {
    const unit = { minute: 6e4, hour: 36e5, day: 864e5, week: 6048e5, month: 2592e6, year: 31536e6 };
    return new Date(Date.now() - parseInt(rel[1], 10) * unit[rel[2]]).toISOString();
  }

  // A bare number as a string is ambiguous — "8" parses as the year 2001.
  if (/^\d{1,4}$/.test(raw)) return null;

  const parsed = new Date(raw);
  return isNaN(parsed.getTime()) ? null : parsed.toISOString();
}


/*
 * jobs.region_id is a FK to regions(id); the collectors only know a country
 * code, so resolve it here. An unknown code becomes null rather than failing
 * the batch — a job with no region still belongs in the shared pool.
 */
const regionByCode = new Map(
  $('Fetch Regions').all()
    .map(i => i.json)
    .filter(r => r && r.country_code)
    .map(r => [String(r.country_code).toUpperCase(), r.id])
);
if (regionByCode.size === 0) console.log('WARNING: no regions loaded — every region_id will be null');

// The seeded Worldwide row carries no country code, so it can only be found by
// name. Remote-anywhere terms belong to it rather than to no region at all.
const worldwideRegionId = ($('Fetch Regions').all()
  .map(i => i.json)
  .find(r => r && !r.country_code && String(r.name || '').toLowerCase() === 'worldwide') || {}).id ?? null;

function toRegionId(code, worldwide) {
  if (code) return regionByCode.get(String(code).toUpperCase()) ?? null;
  return worldwide ? worldwideRegionId : null;
}

const items = $input.all().map(i => i.json).filter(j => j && j.apply_url && j.title);
const target = $input.first().json._target || {};

if (items.length === 0) {
  return [{ json: { _empty: true, rows: [], found: 0, term: target.term || '', countryCode: target.countryCode || null } }];
}

const rows = items.map(j => ({
  title: String(j.title).substring(0, 300),
  company: String(j.company || 'Unknown').substring(0, 200),
  location: String(j.location || '').substring(0, 200),
  job_type: JOB_TYPES.includes(j.job_type) ? j.job_type : 'onsite',
  description: String(j.description || '').substring(0, 8000),
  apply_url: j.apply_url,
  salary_text: j.salary_text || null,
  posted_at_source: toTimestamp(j.posted_at_source),
  // Scoring is per-user and happens later, so the pool stores no score and no
  // seniority guess — only what the source actually said.
  source_id: toSourceId(j.source_key),
  region_id: toRegionId(j._countryCode || target.countryCode, target.worldwide),
  external_id: String(j.external_id || j.apply_url).substring(0, 200),
  is_relevant: true,
  is_active: true
}));

console.log('Prepared ' + rows.length + ' rows for "' + (target.term || '?') + '"');
return [{ json: { _empty: false, rows, found: rows.length, term: target.term || '', countryCode: target.countryCode || null } }];

const COLLECTOR = 'apify';
// Records what the run actually did. Scheduled collectors are unattended, so
// "did the 03:00 run work" needs an answer that does not involve opening n8n.
const prepared = $('Prepare Job Rows').first().json;
const response = $input.first().json;

let inserted = 0;
if (Array.isArray(response)) inserted = response.length;
else if (Array.isArray(response.body)) inserted = response.body.length;

const ok = !(response && response.code && response.message);

return [{ json: {
  collector: COLLECTOR,
  term: prepared.term || null,
  country_code: prepared.countryCode || null,
  found: prepared.found || 0,
  inserted,
  ok,
  detail: ok ? null : String(response.message).substring(0, 400)
} }];

/*
 * The webhook is the trust boundary, and n8n leaves it open by default.
 *
 * Everything past this node spends the named user's Apify credit, so an
 * unauthenticated caller must not get to choose whose. Without this check a
 * POST to the public webhook URL with someone else's id drains their balance.
 *
 * Belt and braces: also switch the webhook node to Header Auth in n8n, which
 * stops the request before the workflow runs at all.
 */
const cfg = $('Set Config').first().json;
const trigger = $('On Search Pressed').first().json;
const headers = trigger.headers || {};

const provided = String(headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '');
const expected = String(cfg.webhookSecret || '');

// Compared in constant time, and never reported back to the caller in detail.
if (!expected || provided.length !== expected.length) throw new Error('Unauthorized');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized');

/*
 * The id is interpolated into a URL downstream and decides whose token is
 * spent, so it has to look like one of ours before it goes anywhere. A strict
 * uuid shape also removes any question of query-string injection.
 */
const userId = String((trigger.body || {}).userId || '');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(userId)) {
  throw new Error('Invalid userId');
}

return [{ json: { ...cfg, userId } }];
